import { Meta, StoryObj } from "@storybook/react";
import { useEffect, useRef, useState } from "react";
import styles from "./colors.stories.module.less";
import { desktopOnlyMode } from "../../.storybook/preview";

const steps = [100, 200, 300, 400, 500, 600, 700, 800, 900];

const palette = (name: string) => steps.map((step) => `--foundation-color-${name}-${step}`);

const themeColors = ["primary", "secondary", "tertiary", "quaternary"].flatMap(palette);

const sharedColors = [
  ...["natural", "information", "error", "warning", "success"].flatMap(palette),
  "--foundation-color-white",
  "--foundation-color-black",
];

/**
 * Shows only the colors the current theme defines (i.e. hide quaternary if not defined).
 * Which variables exist is only known in the browser, so it is read from the computed style.
 *
 * `theme` is not read inside the effect, but it is needed as a dependency to trigger a re-read.
 */
const ColorPalette = ({ colors, theme }: { colors: Array<string>; theme: string }) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const [definedColors, setDefinedColors] = useState(colors);

  useEffect(() => {
    if (!rootRef.current) return;

    const computedStyle = getComputedStyle(rootRef.current);

    setDefinedColors(colors.filter((colorVariable) => computedStyle.getPropertyValue(colorVariable).trim() !== ""));
  }, [colors, theme]);

  return (
    <div className={styles.root} ref={rootRef}>
      {definedColors.map((colorVariable) => (
        <div className={styles.item} key={colorVariable}>
          <p>{colorVariable}</p>
          <div style={{ backgroundColor: `var(${colorVariable})` }} />
        </div>
      ))}
    </div>
  );
};

const meta = {
  title: "Foundation/Colors",
  parameters: {
    chromatic: desktopOnlyMode,
  },
} satisfies Meta;

export default meta;

export const Primary = {
  render: (_args, context) => <ColorPalette colors={themeColors} theme={context.globals.theme} />,
} satisfies StoryObj<typeof meta>;

/** Colors every theme shares, from foundation.less. */
export const Shared = {
  render: (_args, context) => <ColorPalette colors={sharedColors} theme={context.globals.theme} />,
} satisfies StoryObj<typeof meta>;
